<script setup lang="ts">import {ref,onMounted} from 'vue';import {api} from '../../api';import {t} from '../../locales';import '../../styles/app.scss';const data=ref<any>({title:t('说明'),body:'',version:''});onMounted(async()=>{const type=(getCurrentPages().at(-1) as any)?.options?.type||'about';data.value=await api.staticContent(type);if(type==='about'){try{const version:any=await api.appVersion();data.value.version=version?.version||version?.appVersion||''}catch{}}})</script>
<template><view class="inner-page"><view class="inner-nav"><text class="back" @click="uni.navigateBack()">‹</text><text class="nav-title">{{data.title}}</text></view><view class="inner-main"><view class="inner-card content-card"><view class="content-title">{{data.title}}</view><view class="content-body">{{data.body}}</view></view><view class="content-foot">Crypto Flash · {{data.version || 'V1.0.0'}}</view></view></view></template><style scoped>.content-card{margin-top:4rpx}.content-title{font-size:25rpx;font-weight:800}.content-body{margin-top:22rpx;color:var(--cf-muted);font-size:23rpx;line-height:1.9;white-space:pre-line}.content-foot{margin-top:18rpx;color:var(--cf-soft);font-size:17rpx;text-align:center}</style>
